mutations.find:
import type { HighlighterCore, LanguageInput } from "shiki/core";

/** Shiki's core and its JavaScript regex engine, loaded on the first highlight. */
const loadShiki = () => Promise.all([import("shiki/core"), import("shiki/engine/javascript")]);

mutations.replace:
import * as shikiCore from "shiki/core";
type HighlighterCore = shikiCore.HighlighterCore;
type LanguageInput = shikiCore.LanguageInput;

/** Shiki's core and its JavaScript regex engine, loaded on the first highlight. */
const loadShiki = () => Promise.all([Promise.resolve(shikiCore), import("shiki/engine/javascript")]);
